={
  "model": "claude-3-5-sonnet-20241022",
  "max_tokens": 2000,
  "system": "Eres el redactor jefe de marketing editorial para librerías independientes y cuentas de Bookstagram. Transforma la foto de la portada o los datos del libro en un carrusel de Instagram de 5 diapositivas (cover_hook, quote, synopsis, highlights, cta) y un caption con hashtags. Responde ÚNICA Y EXCLUSIVAMENTE con un JSON válido sin texto adicional ni markdown: {\"title\": \"...\", \"author\": \"...\", \"genre\": \"...\", \"publisher\": \"...\", \"review\": \"...\", \"quote\": \"...\", \"caption\": \"...\", \"hashtags\": [\"#libros\", ...], \"slides\": [{\"type\": \"cover_hook\", \"category\": \"RECOMENDACIÓN EDITORIAL\", \"title\": \"...\", \"subtitle\": \"...\"}, {\"type\": \"quote\", \"category\": \"CITA INOLVIDABLE\", \"title\": \"LA VOZ DEL AUTOR\", \"quote\": \"...\", \"subtitle\": \"...\"}, {\"type\": \"synopsis\", \"category\": \"LA PREMISA\", \"title\": \"EL CORAZÓN DEL RELATO\", \"body\": \"...\"}, {\"type\": \"highlights\", \"category\": \"VEREDICTO LIBRERO\", \"title\": \"¿POR QUÉ DEBES LEERLO HOY?\", \"body\": \"...\"}, {\"type\": \"cta\", \"category\": \"DISPONIBILIDAD\", \"title\": \"EN TODAS NUESTRAS SUCURSALES\", \"body\": \"...\"}]}",
  "messages": [
    {
      "role": "user",
      "content": $json.body.imageBase64 ? [
        {
          "type": "image",
          "source": {
            "type": "base64",
            "media_type": ($json.body.imageBase64.includes('image/png') ? 'image/png' : 'image/jpeg'),
            "data": $json.body.imageBase64.replace(/^data:image\/\w+;base64,/, '')
          }
        },
        {
          "type": "text",
          "text": "Analiza la foto de este libro. Identifica título, autor, editorial, redacta la reseña literaria apasionada y genera las 5 diapositivas para el carrusel de Instagram de nuestra librería."
        }
      ] : [
        {
          "type": "text",
          "text": "LIBRO: " + ($json.body.bookTitle || '') + "\nAUTOR: " + ($json.body.bookAuthor || '') + "\nRESEÑA:\n" + ($json.body.reviewText || '')
        }
      ]
    }
  ]
}

={
  "book": {
    "title": JSON.parse($json.content[0].text.replace(/```json\n?|```/g, '')).title || $('Webhook: Iniciar Generación').item.json.body.bookTitle,
    "author": JSON.parse($json.content[0].text.replace(/```json\n?|```/g, '')).author || $('Webhook: Iniciar Generación').item.json.body.bookAuthor,
    "genre": JSON.parse($json.content[0].text.replace(/```json\n?|```/g, '')).genre || $('Webhook: Iniciar Generación').item.json.body.genre,
    "coverImageUrl": $('Webhook: Iniciar Generación').item.json.body.coverImageUrl || $('Webhook: Iniciar Generación').item.json.body.imageBase64
  },
  "bookstore": $('Webhook: Iniciar Generación').item.json.body.bookstore,
  "theme": $('Webhook: Iniciar Generación').item.json.body.theme || 'editorial_classic',
  "aspectRatio": $('Webhook: Iniciar Generación').item.json.body.aspectRatio || '4:5',
  "slides": JSON.parse($json.content[0].text.replace(/```json\n?|```/g, '')).slides
}
